const jnb = { local: "2024-03-01T14:00", zone: "Africa/Johannesburg" };
test("an ETA 2h01m after the promised time sends one notice that is 121 minutes late (AC-1)", () => {
  assert.equal(code.toUtc(jnb), "2024-03-01T12:00Z");
  assert.equal(code.minutesLate(jnb, "2024-03-01T14:01Z"), 121);
  const n = code.createNotifier();
  assert.deepEqual(n.update("S1", jnb, "2024-03-01T14:01Z"), { id: "S1", late: 121 });
  assert.match(code.formatForCustomer("2024-03-01T14:01Z", "Africa/Johannesburg"), /1 Mar, 16:01/);
});
test("an ETA exactly 2h00m late sends nothing, and a later 2h01m ETA still sends the first notice (AC-2)", () => {
  const n = code.createNotifier();
  assert.equal(code.minutesLate(jnb, "2024-03-01T14:00Z"), 120);
  assert.equal(n.update("S2", jnb, "2024-03-01T14:00Z"), null);
  assert.deepEqual(n.update("S2", jnb, "2024-03-01T14:01Z"), { id: "S2", late: 121 });
});
test("second notice only when the ETA slips 2h or more past the first notice ETA, then nothing more (AC-3)", () => {
  const n = code.createNotifier();
  assert.deepEqual(n.update("S3", jnb, "2024-03-01T14:01Z"), { id: "S3", late: 121 });
  assert.equal(n.update("S3", jnb, "2024-03-01T16:00Z"), null);
  assert.deepEqual(n.update("S3", jnb, "2024-03-01T16:01Z"), { id: "S3", late: 241 });
  assert.equal(n.update("S3", jnb, "2024-03-01T18:30Z"), null);
  assert.match(code.formatForCustomer("2024-03-01T16:01Z", "Africa/Johannesburg"), /1 Mar, 18:01/);
});
test("a late ETA that crosses midnight shows the next local date and time (AC-4)", () => {
  const p = { local: "2024-03-01T23:00", zone: "Africa/Johannesburg" };
  assert.equal(code.minutesLate(p, "2024-03-02T00:30Z"), 210);
  const n = code.createNotifier();
  assert.deepEqual(n.update("S4", p, "2024-03-02T00:30Z"), { id: "S4", late: 210 });
  assert.equal(code.formatForCustomer("2024-03-02T00:30Z", "Africa/Johannesburg"), "2 Mar, 02:30 (Johannesburg time)");
});
test("India and New York times convert and display with their labels, including New York daylight time", () => {
  assert.equal(code.toUtc({ local: "2024-11-12T21:00", zone: "Asia/Kolkata" }), "2024-11-12T15:30Z");
  assert.equal(code.formatForCustomer("2024-11-12T15:30Z", "Asia/Kolkata"), "12 Nov, 21:00 (India time)");
  assert.equal(code.toUtc({ local: "2024-03-10T12:00", zone: "America/New_York" }), "2024-03-10T16:00Z");
  assert.equal(code.formatForCustomer("2024-03-10T18:01Z", "America/New_York"), "10 Mar, 14:01 (New York time)");
});
test("an early ETA gives negative minutes and sends nothing, and a malformed ETA is rejected", () => {
  assert.equal(code.minutesLate(jnb, "2024-03-01T11:30Z"), -30);
  const n = code.createNotifier();
  assert.equal(n.update("S6", jnb, "2024-03-01T11:30Z"), null);
  assert.throws(() => code.minutesLate(jnb, "2024-03-01 14:01"), /Invalid UTC time/);
});

testScript:
test("sends a notice when the latest carrier ETA is more than 2 hours after the promised time", function() {
  var zone = "Africa/Johannesburg";
  var promised = { local: "2024-11-12T14:00", zone };
  var eta = "2024-11-12T14:01Z";
  assert.equal(code.toUtc(promised), "2024-11-12T12:00Z");
  assert.equal(code.minutesLate(promised, eta), 121);
  assert.deepEqual(code.createNotifier().update("s1", promised, eta), { id: "s1", late: 121 });
  assert.match(code.formatForCustomer(eta, zone), /^12 Nov, 16:01/);
});
test("does not send a notice when the ETA is exactly 2 hours late", function() {
  var promised = { local: "2024-11-12T14:00", zone: "Africa/Johannesburg" };
  var eta = "2024-11-12T14:00Z";
  assert.equal(code.toUtc(promised), "2024-11-12T12:00Z");
  assert.equal(code.minutesLate(promised, eta), 120);
  assert.equal(code.createNotifier().update("s2", promised, eta), null);
});
test("does not send a notice when the delay is under 2 hours", function() {
  var promised = { local: "2024-11-12T14:00", zone: "Africa/Johannesburg" };
  var eta = "2024-11-12T13:59Z";
  assert.equal(code.minutesLate(promised, eta), 119);
  assert.equal(code.createNotifier().update("s3", promised, eta), null);
});
test("compares ETA and promised time as absolute instants and shows the delivery address local date and time", function() {
  var zone = "Africa/Johannesburg";
  var promised = { local: "2024-03-01T23:00", zone };
  var eta = "2024-03-02T00:30Z";
  assert.equal(code.toUtc(promised), "2024-03-01T21:00Z");
  assert.equal(code.minutesLate(promised, eta), 210);
  assert.deepEqual(code.createNotifier().update("s4", promised, eta), { id: "s4", late: 210 });
  var shown = code.formatForCustomer(eta, zone);
  assert.match(shown, /^0?2 Mar, 02:30/);
  assert.equal(shown.indexOf("00:30"), -1);
  assert.equal(shown.indexOf("1 Mar"), -1);
});
test("sends a second notice when a later ETA is exactly 2 hours beyond the ETA in the first notice", function() {
  var zone = "Africa/Johannesburg";
  var promised = { local: "2024-11-12T14:00", zone };
  var notifier = code.createNotifier();
  assert.deepEqual(notifier.update("s5", promised, "2024-11-12T14:01Z"), { id: "s5", late: 121 });
  var eta = "2024-11-12T16:01Z";
  assert.equal(code.minutesLate(promised, eta), 241);
  assert.deepEqual(notifier.update("s5", promised, eta), { id: "s5", late: 241 });
  assert.match(code.formatForCustomer(eta, zone), /^12 Nov, 18:01/);
});
test("does not send a second notice when the further slip is under 2 hours past the first notice ETA", function() {
  var promised = { local: "2024-11-12T14:00", zone: "Africa/Johannesburg" };
  var notifier = code.createNotifier();
  assert.deepEqual(notifier.update("s6", promised, "2024-11-12T14:01Z"), { id: "s6", late: 121 });
  var eta = "2024-11-12T16:00Z";
  assert.equal(code.minutesLate(promised, eta), 240);
  assert.equal(notifier.update("s6", promised, eta), null);
});
test("sends at most two notices and sends nothing after the second", function() {
  var promised = { local: "2024-11-12T14:00", zone: "Africa/Johannesburg" };
  var notifier = code.createNotifier();
  assert.deepEqual(notifier.update("s7", promised, "2024-11-12T14:01Z"), { id: "s7", late: 121 });
  assert.deepEqual(notifier.update("s7", promised, "2024-11-12T16:01Z"), { id: "s7", late: 241 });
  var eta = "2024-11-12T18:01Z";
  assert.equal(code.minutesLate(promised, eta), 361);
  assert.equal(notifier.update("s7", promised, eta), null);
});
test("evaluates only the latest ETA so a prior non-triggering ETA does not block the first notice", function() {
  var zone = "Africa/Johannesburg";
  var promised = { local: "2024-11-12T14:00", zone };
  var notifier = code.createNotifier();
  assert.equal(code.minutesLate(promised, "2024-11-12T14:00Z"), 120);
  assert.equal(notifier.update("s8", promised, "2024-11-12T14:00Z"), null);
  var eta = "2024-11-12T14:01Z";
  assert.equal(code.minutesLate(promised, eta), 121);
  assert.deepEqual(notifier.update("s8", promised, eta), { id: "s8", late: 121 });
  assert.match(code.formatForCustomer(eta, zone), /^12 Nov, 16:01/);
});

